namespace CodeDesignPlus.Net.Microservice.Payments.Application.Payout.DataTransferObjects;

/// <summary>
/// A payment to a third party as the calling module sees it. Never carries the bank account.
/// </summary>
public class PayoutDto
{
    /// <summary>
    /// Id of the payout, generated by the calling module.
    /// </summary>
    public Guid Id { get; set; }

    /// <summary>
    /// Tenant whose collection account pays.
    /// </summary>
    public Guid Tenant { get; set; }

    /// <summary>
    /// Module that asked for the payout.
    /// </summary>
    public string Module { get; set; } = null!;

    /// <summary>
    /// Id of what is being paid in the calling module.
    /// </summary>
    public Guid ReferenceId { get; set; }

    /// <summary>
    /// Why the money leaves the account.
    /// </summary>
    public PayoutPurpose Purpose { get; set; }

    /// <summary>
    /// Amount to pay.
    /// </summary>
    public Net.ValueObjects.Financial.Money Amount { get; set; } = null!;

    /// <summary>
    /// Current state.
    /// </summary>
    public PayoutStatus Status { get; set; }

    /// <summary>
    /// Code of the provider that pays it, once sent.
    /// </summary>
    public string? Provider { get; set; }

    /// <summary>
    /// Id of the provider's batch, once sent.
    /// </summary>
    public string? ProviderBatchId { get; set; }

    /// <summary>
    /// Id of the transaction inside the provider's batch, once sent.
    /// </summary>
    public string? ProviderTransactionId { get; set; }

    /// <summary>
    /// Reason given by the provider when the payout failed.
    /// </summary>
    public string? FailureReason { get; set; }

    /// <summary>
    /// Builds the view of a payout.
    /// </summary>
    /// <param name="payout">The payout.</param>
    /// <returns>Its view.</returns>
    public static PayoutDto From(PayoutAggregate payout) => new()
    {
        Id = payout.Id,
        Tenant = payout.Tenant,
        Module = payout.Module,
        ReferenceId = payout.ReferenceId,
        Purpose = payout.Purpose,
        Amount = payout.Amount,
        Status = payout.Status,
        Provider = payout.Provider,
        ProviderBatchId = payout.ProviderBatchId,
        ProviderTransactionId = payout.ProviderTransactionId,
        FailureReason = payout.FailureReason
    };
}
